import{_ as s,l as i,o as e,c as n,v as t,p as l,x as r,d as p,i as _,S as E}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"状态依存与或有要求权","description":"","frontmatter":{"title":"状态依存与或有要求权","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/state-contingent.md","filePath":"econ/state-contingent.md","lastUpdated":1789023840000}'),A={name:"econ/state-contingent.md"};function d(c,a,h,u,B,m){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="状态依存与或有要求权" tabindex="-1">状态依存与或有要求权 <a class="header-anchor" href="#状态依存与或有要求权" aria-label="Permalink to &quot;状态依存与或有要求权&quot;">​</a></h1><div class="epigraph"><p>最优风险分担不要求再发明一种商品：只要每个状态有一张只在该状态支付的证券，竞争价格就能完成配置。</p><footer>—— 据 Arrow, The Role of Securities in the Optimal Allocation of Risk-Bearing, Review of Economic Studies, 1964（1953 年法文稿）整理</footer></div><p><a href="/econ/third-order-sd">上一课</a>（三阶占优）。在无名财富的分布上给偏序。本课不重讲 FSD/SSD，也不再估 \\(r_A\\)。缺口是：轮盘彩票把结果当成可交换的数字，市场里的风险却绑在有名字的状态上——下雨、违约、衰退。没有状态，就没有可交易的或有要求权，后课一般均衡也无法把不确定性写进商品空间。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/econ/expected-utility">期望效用</a>的对象是 \\(\\Delta(X)\\)：同一财富数字在任何实现里可互换。若状态 \\(s\\in S\\) 有经济含义，消费是向量 \\(x=(x_s)_{s\\in S}\\)，偏好是</p> \\[U(x)=\\sum_{s\\in S}\\pi_s u(x_s), \\]<p>概率 \\(\\pi\\) 仍客观，但 \\(x_s\\) 不能再被重排。占优只看见 \\(x\\) 诱导的分布，看不见「哪一个 \\(s\\) 穷」。缺口是把商品重新定义为<strong>状态依存消费</strong>，并把最简单的资产定为 Arrow 证券：状态 \\(s\\) 的证券在 \\(s\\) 支付一单位计价物、其余状态支付零。</p><p>完全市场：Arrow 证券张成整个 \\(\\mathbb{R}^S\\)，任何或有束都可以当一篮子买到。预算变成 \\(\\sum_s q_s x_s=w\\)，其中 \\(q_s\\) 是状态价格。不完全市场是后课宏观与公司金融的缺口；本课只钉完全这一端。</p><h3 id="彩票与或有商品不是同一菜单" tabindex="-1">彩票与或有商品不是同一菜单 <a class="header-anchor" href="#彩票与或有商品不是同一菜单" aria-label="Permalink to &quot;彩票与或有商品不是同一菜单&quot;">​</a></h3><p>把状态上的 \\(x\\) 推成财富的分布，再拿 SSD 排序，会丢掉状态之间的价格信息。两份分布相同的或有束，在 \\(q\\) 不与 \\(\\pi\\) 成比例时，预算成本可以不同。占优仍用于「同一预算下哪份分布更好」；配置问题要用 \\(q\\)。不要把上一课的积分条件直接写成资产需求。</p><p><span class="marginnote">主观概率是 Savage；本课 \\(\\pi\\) 给定。状态价格 \\(q_s\\) 不必等于 \\(\\pi_s\\)：风险厌恶者让倒霉状态更贵。后课随机折现因子把 \\(q_s/\\pi_s\\) 叫状态价格密度，这里只需要比值存在。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>有限状态、有限个人。每人禀赋 \\(\\omega=(\\omega_s)\\)，在完全的 Arrow 市场上选 \\(x\\)，使 \\(\\mathbb{E}u(x)\\) 最大。一阶条件是 \\(\\pi_s u&#39;(x_s)=\\lambda q_s\\)。两人之间，最优风险分担要求状态间的 MRS 对齐：</p> \\[\\frac{\\pi_s u_A&#39;(x_s^A)}{\\pi_t u_A&#39;(x_t^A)}=\\frac{\\pi_s u_B&#39;(x_s^B)}{\\pi_t u_B&#39;(x_t^B)}=\\frac{q_s}{q_t}. \\]<p>若两人同权并都是凹 \\(u\\)，则更倒霉的状态里两人一起少消费，而不是把全部风险推给一个人。这与<a href="/econ/risk-aversion">风险厌恶</a>的公平保险全额投保是同一线性期望结构，只是状态有了名字。</p>',15)),(e(),l(E,null,{default:r(()=>[_(o,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIST%5B%22%E6%97%A0%E5%90%8D%E5%88%86%E5%B8%83%E4%B8%8E%E5%8D%A0%E4%BC%98%22%5D%20--%3E%20ST%5B%22%E7%8A%B6%E6%80%81%20s%20%E4%B8%8A%E7%9A%84%E6%B6%88%E8%B4%B9%20x_s%22%5D%0A%20%20ST%20--%3E%20ARROW%5B%22Arrow%20%E8%AF%81%E5%88%B8%EF%BC%9A%E5%AE%8C%E5%85%A8%E5%B8%82%E5%9C%BA%22%5D%0A%20%20ARROW%20--%3E%20Q%5B%22%E7%8A%B6%E6%80%81%E4%BB%B7%E6%A0%BC%20q%22%5D%0A%20%20Q%20--%3E%20SHARE%5B%22MRS%20%E5%AF%B9%E9%BD%90%EF%BC%9A%E6%9C%80%E4%BC%98%E5%88%86%E6%8B%85%22%5D%0A%20%20SHARE%20--%3E%20LATER%5B%22%E4%B8%8B%E8%AF%BE%E7%A8%8B%EF%BC%9A%E6%8A%8A%20x%20%E6%8D%A2%E6%88%90%E7%94%9F%E4%BA%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>本课不引入生产。或有商品可以后补进生产集，但技术和成本是下一课程的对象。也不把 Arrow 证券写成限价簿上的合约清单。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>独立性把跨状态的权衡收成逐点的 \\(u&#39;(x_s)\\)，概率当权重；市场把同一权衡标成 \\(q_s\\)。二者相除，得到「一单位概率在状态 \\(s\\) 值多少」。风险厌恶（凹）让 \\(u&#39;\\) 在穷状态更高，故穷状态的 \\(q_s/\\pi_s\\) 更高——这就是风险溢价在完全市场上的微观来源。没有状态名字，溢价只能停留在分布的 SSD 上，不能写成可交易的价差。</p><p>完全性的机制是张成：任何再分配都等价于 Arrow 篮子的组合。缺一张证券，就有一个不能对冲的方向，分担条件只在可张成的子空间上成立。本课标明这个刀刃，但不展开不完全市场的一般理论。</p><p><span class="marginnote">Debreu《价值理论》把商品写成（物理、时间、地点、事件）。Arrow 的贡献是：不必为每个或有商品开一个现货市场，一组证券即可。后课福利定理默认的是这一商品空间。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(S\\) 有限、\\(\\pi\\) 客观、市场完全，是本课的工作假设。连续状态要用测度；模糊与阿莱对照仍在课序前段，这里不把问卷搬进 Arrow 价格。也不处理道德风险下「状态不可验证」——那是信息课的隐藏行动，不是或有商品缺定义。</p><p>不确定课序在此结束。下一课程换对象：决策者不再只是带着禀赋买或有束的消费者，而是把投入变成产出的技术。不要把生产函数写成状态上的 \\(u\\)。</p><p>道德风险会让某些或有合同写不成，那是信息课。连续状态需要测度与无限证券，主干用有限 \\(S\\)。量化栏的成交机制不是状态指标：本课定义契约按状态交付，不定义谁先报价。</p><p>后课默认：不确定性下的商品是状态依存的；完全市场用状态价格 \\(q\\) 配置风险。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>状态给结果起名字；Arrow 证券把或有消费变成可交易篮子。</li><li>完全市场上最优分担即状态间 MRS 等于状态价格比。</li><li>占优比较无名分布；配置要用 \\(q\\)，二者不要焊死。</li><li>不确定课序到此；下一课打开技术与成本。</li><li>出处：Arrow, <em>Review of Economic Studies</em>, 1964；Debreu, <em>Theory of Value</em>, 1959；Mas-Colell, Whinston and Green 第 6 章。</li></ul>',12))])}const f=s(A,[["render",d]]);export{x as __pageData,f as default};
